CREATE TABLE [dbo].[ivrcallsin](	  [IVR_id] INT NOT NULL IDENTITY(1,1)	, [cal_ani] VARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [date] DATETIME NOT NULL	, [dnis] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [callout_id] INT NULL	, [tincall] INT NULL	, CONSTRAINT [PK_IVR_ID_1] PRIMARY KEY ([IVR_id] ASC))CREATE NONCLUSTERED INDEX [IX_ivrcallsin] ON [dbo].[ivrcallsin] ([date] ASC)